import { readFileSync, writeFileSync } from 'node:fs'

// Tracked JSON is the source of truth. The build embeds it as MoonBit strings.
const entries = [
  ['schema_json', 'schema.json'],
  ['bump_lookup_json', 'bump_confirmed_lookup.json'],
  ['bump_evidence_json', 'bump_lookup_evidence.json'],
]
const source =
  '// Generated by scripts/embed-data.mjs. Edit data/*.json instead.\n' +
  entries
    .map(([name, file]) => {
      const data = JSON.parse(readFileSync(new URL(`../data/${file}`, import.meta.url), 'utf8'))
      return `\n///|\nlet ${name} : String = ${JSON.stringify(JSON.stringify(data))}\n`
    })
    .join('')
const target = new URL('../data.mbt', import.meta.url)
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== source) {
    throw new Error('data.mbt is stale. Run node scripts/embed-data.mjs in packages/yki-core.')
  }
} else {
  writeFileSync(target, source)
}
